<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$v=[trim($_POST['full_name']??''),trim($_POST['email']??''),trim($_POST['headline']??''),trim($_POST['skills']??''),trim($_POST['portfolio_url']??''),trim($_POST['location']??''),$_POST['status']??'pending'];if($v[0]===''){flash('Full name is required.');}elseif($id){$q=$pdo->prepare('UPDATE talent_profiles SET full_name=?,email=?,headline=?,skills=?,portfolio_url=?,location=?,status=? WHERE id=?');$q->execute([...$v,$id]);flash('Talent profile updated.');}else{$q=$pdo->prepare('INSERT INTO talent_profiles(full_name,email,headline,skills,portfolio_url,location,status) VALUES(?,?,?,?,?,?,?)');$q->execute($v);flash('Talent profile added.');}}elseif($a==='delete'){$q=$pdo->prepare('DELETE FROM talent_profiles WHERE id=?');$q->execute([(int)$_POST['id']]);flash('Talent profile deleted.');}header('Location: talents.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM talent_profiles WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM talent_profiles ORDER BY created_at DESC')->fetchAll();$pageTitle='Talent profiles';include __DIR__.'/_header.php';?>
<div class="dash-top"><div><span class="eyebrow">Talent network</span><h1>Talent profiles</h1><p>Manage professional profiles and control which ones appear publicly.</p></div></div><section class="dash-panel"><h2><?= $edit?'Edit profile':'Add a talent profile'?></h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-row"><label>Full name<input name="full_name" required value="<?=e($edit['full_name']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label></div><label>Professional headline<input name="headline" placeholder="e.g. Front-end developer" value="<?=e($edit['headline']??'')?>"></label><label>Skills (separate with commas)<textarea name="skills" rows="2"><?=e($edit['skills']??'')?></textarea></label><div class="form-row"><label>Portfolio URL<input name="portfolio_url" value="<?=e($edit['portfolio_url']??'')?>"></label><label>Location<input name="location" value="<?=e($edit['location']??'Plateau State')?>"></label></div><label>Status<select name="status"><?php foreach(['pending','published'] as $s):?><option <?=$s===($edit['status']??'pending')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="btn">Save profile</button> <?php if($edit):?><a class="btn btn-outline" href="talents.php">Cancel</a><?php endif;?></form></section><section class="dash-panel"><h2>All talent profiles (<?=count($rows)?>)</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Headline</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small><?=e($r['email'])?></small></td><td><?=e($r['headline'])?></td><td><?=e($r['location'])?></td><td><span class="status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td class="actions"><a href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this profile?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No talent profiles yet.</td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__.'/_footer.php';?>